INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('785dac40-bf87-4da9-9a2d-bd6f87b49a4a', 'valida-regex', 'valida_regex', 'exec', 19, 1, '{"code" : "module.exports=async function(data){const{first_name,last_name,location,title}=data.$trigger.payload;const nameRegex=/^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ\\\\s''-]+$/;const validateNameField=(fieldName,value)=>{if(!value)return true;if(!nameRegex.test(value)){const invalidChars=[...new Set(value.match(/[^A-Za-zÁÉÍÓÚÜÑáéíóúüñ\\\\s''-]/g))];throw{message:`El campo ${fieldName.toUpperCase()} contiene caracteres no permitidos (${invalidChars.join(\", \")}). Solo se aceptan letras del alfabeto latino (con o sin acento), Ñ/ñ, Ü/ü, espacios, apóstrofes ('') y guiones (-).`,extensions:{code:\"FAILED_VALIDATION\",field:fieldName,type:\"regex\",invalid:value}};}return true;};try{validateNameField(\"Nombre\",first_name);validateNameField(\"Apellido\",last_name);validateNameField(\"Ubicación\",location);validateNameField(\"Título\",title);return data;}catch(error){throw error;}};"}', NULL, NULL, '53a5b81e-ace6-41b7-b0cb-dfc9938e3b72', '2025-11-05 23:22:18.120569+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('45d1a25e-2832-4b30-b81e-2ca79be7e59e', 'Ejecutar script', 'exec_eegtp', 'exec', 18, 1, '{"code":"module.exports = async function(data) {\n  const trigger = data.$trigger || {};\n  const keys = trigger.keys;\n\n  const esUpdate = Array.isArray(keys) && keys.length > 0;\n  const idOriginal = esUpdate ? keys[0] : null;\n\n   console.log(esUpdate,\"😒😒😒😒😒😒😒😒😒😒😒😒\");\n  return { esUpdate, idOriginal };\n};\n"}', '9b38acb1-68a3-42eb-8711-515b164d37b2', NULL, '77777777-7777-7777-7777-777777777777', '2025-11-26 16:42:50.486+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ef574dda-140b-4fc9-9bf8-25db2eb5a46e', 'Ejecutar script', 'exec_pj6o2_uvddk', 'exec', 105, 17, '{"code":"\n\nmodule.exports = async function (data) {\n  const iniciales = data.inicialesEsperadasU?.inicialesEsperadas || ''N/A'';\n  const { curpPrefix, rfcPrefix, curpCoincide, rfcCoincide } = data.datosBooleanosU || {};\n\n  // 🧩 Caso 1: Ambos incorrectos\n  if (!curpCoincide && !rfcCoincide) {\n    throw new Error(\n      `❌ Inconsistencia detectada: \n      Las iniciales esperadas (${iniciales}) no coinciden ni con la CURP (${curpPrefix}) ni con el RFC (${rfcPrefix}). \n     Verifica que nombre, apellidos, CURP y RFC correspondan correctamente.`\n    );\n  }\n\n  // 🧩 Caso 2: Solo CURP incorrecta\n  if (!curpCoincide && rfcCoincide) {\nthrow new Error(\n    `⚠️ Inconsistencia parcial:\n   Las iniciales esperadas (${iniciales}) coinciden con el RFC (${rfcPrefix}) pero no con la CURP (${curpPrefix}). \n      Revisa la CURP, podría haberse capturado de forma incorrecta.`\n    );\n    \n  }\n\n  // 🧩 Caso 3: Solo RFC incorrecta\n  if (curpCoincide && !rfcCoincide) {\n    throw new Error(\n      `⚠️ Inconsistencia parcial:\n      Las iniciales esperadas (${iniciales}) coinciden con la CURP (${curpPrefix}) pero no con el RFC (${rfcPrefix}). \n      Revisa el RFC, podría haberse capturado de forma incorrecta.`\n    );\n  }\n\n  // ✅ Caso 4: Todo correcto\n  return {\n    message: `✅ Validación CURP/RFC exitosa: las iniciales (${iniciales}) coinciden correctamente con la CURP (${curpPrefix}) y el RFC (${rfcPrefix}).`\n  };\n};\n\n"}', NULL, NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 17:35:51.211+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4d6806f2-3fe6-40c8-87fa-06b79b3cd68f', 'validar datos', 'validar_datos', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const payload = data.$trigger?.payload || {};\n    const nameRegex = /^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ\\s''-]+$/;\n    \n    const errores = [];\n    \n    const validarCampo = (valor, nombreCampo) => {\n        if (!valor || valor.trim() === '''') return;\n        \n        if (!nameRegex.test(valor)) {\n            const invalidChars = [...new Set(\n                valor.match(/[^A-Za-zÁÉÍÓÚÜÑáéíóúüñ\\s''-]/g)\n            )];\n            errores.push(`${nombreCampo} (${invalidChars.join(\", \")})`);\n        }\n    };\n    \n    // Validar todos los campos\n    validarCampo(payload.nombres, ''Nombres'');\n    validarCampo(payload.primerApellido, ''Primer Apellido'');\n    validarCampo(payload.segundoApellido, ''Segundo Apellido'');\n    \n    // Lanzar error único con todos los campos\n    if (errores.length > 0) {\n        throw new Error(\n            `Se encontraron caracteres no permitidos en los siguientes campos: ${errores.join('' | '')}. ` +\n            `Solo se aceptan letras del alfabeto latino, Ñ/ñ, Ü/ü, espacios y acentos`\n        );\n    }\n    \n    return data;\n};"}', NULL, NULL, 'ee87ba34-f26b-4db8-9124-4a519156b5e7', '2025-11-12 22:33:32.456+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('fc341a93-5708-4579-909a-1df6f6e89150', 'imprimir logs', 'imprimir_logs', 'log', 19, 1, '{"message":"{{$trigger.payload}}"}', '4d6806f2-3fe6-40c8-87fa-06b79b3cd68f', NULL, 'ee87ba34-f26b-4db8-9124-4a519156b5e7', '2025-11-12 22:33:32.465+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8524fa2f-25f1-4500-a9b4-d442cf437772', 'Ejecutar script', 'exec_17h3t_tlcqe', 'exec', 79, 35, '{"code":"module.exports = async function (data) {\n  const lista = Array.isArray(data.$last) ? data.$last : [];\n\n  const {\n    curp,\n    rfc,\n    expediente,\n    esUpdate,\n    idOriginal\n  } = data.datosUnificados_apbqe || {};\n\n  console.log(\"VALIDANDO:\", { curp, rfc, expediente, esUpdate, idOriginal, lista });\n\n  const duplicado = lista.find((item) => {\n    const coincidePersona =\n      item.datosGenerales?.curp === curp &&\n      item.datosGenerales?.rfc === rfc;\n\n    const coincideExpediente =\n      item.expediente === expediente;\n\n    // En update: excluirse a sí mismo\n    const noEsElMismo = !esUpdate || item.id !== idOriginal;\n\n    return coincidePersona && coincideExpediente && noEsElMismo;\n  });\n\n  if (duplicado) {\n    const err = new Error(\n      \"⚠ Ya existe una sanción con la misma persona (CURP/RFC) y el mismo expediente.\"\n    );\n    err.status = 400;\n    throw err;\n  }\n\n  return { ok: true };\n};\n"}', NULL, NULL, '77777777-7777-7777-7777-777777777777', '2025-11-26 19:58:12.843+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2f607212-ed54-4bac-880e-5bcd00c6a3e9', 'valida fecha resolución firme', 'valida_fnf', 'exec', 38, 19, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== VALIDACIÓN 2: fechaResolucionFirme >= fechaNotificacion ==='');\n    \n    const fr = data.extraer_fechas.fechaResolucion;\n    const fn = data.extraer_fechas.fechaNotificacion;\n    const frf = data.extraer_fechas.fechaResolucionFirme;\n    const fnf = data.extraer_fechas.fechaNotificacionFirme;\n    const fes = data.extraer_fechas.fechaEjecucion;\n    \n    console.log(''fechaNotificacion:'', fr);\n    console.log(''fechaResolucionFirme:'', frf);\n    \n    if (!fn || !frf) {\n        console.log(''⚠️ Alguna fecha no existe, saltando validación'');\n        return {\n            valido: true,\n            error: null,\n            fechaResolucion: fr,\n            fechaNotificacion: fn,\n            fechaResolucionFirme: frf,\n            fechaNotificacionFirme: fnf,\n            fechaEjecucion: fes\n        };\n    }\n    \n    const timestampFN = new Date(fn).getTime();\n    const timestampFRF = new Date(frf).getTime();\n    \n    console.log(''Timestamp FN:'', timestampFN);\n    console.log(''Timestamp FRF:'', timestampFRF);\n    \n    const valido = timestampFRF >= timestampFN;\n    console.log(''¿Es válido (FRF >= FN)?:'', valido);\n    \n    if (!valido) {\n        console.log(''❌ VALIDACIÓN FALLIDA'');\n        throw new Error(''La Fecha de Resolución Firme no puede ser anterior a la Fecha de Notifación de la Resolución'');\n    }\n    \n    console.log(''✅ VALIDACIÓN EXITOSA'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', 'cc3a6a16-8cb0-48b9-9125-204b2b344863', NULL, 'cf3855aa-ca21-4544-a1f7-ee3351d274cc', '2025-11-26 00:07:16.052+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('dc848ba6-e7c4-4a95-8b06-92681974ee08', 'valida fecha resolución firme', 'valida_fnf', 'exec', 38, 19, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== VALIDACIÓN 2: fechaResolucionFirme >= fechaNotificacion ==='');\n    \n    const fr = data.extraer_fechas.fechaResolucion;\n    const fn = data.extraer_fechas.fechaNotificacion;\n    const frf = data.extraer_fechas.fechaResolucionFirme;\n    const fnf = data.extraer_fechas.fechaNotificacionFirme;\n    const fes = data.extraer_fechas.fechaEjecucion;\n    \n    console.log(''fechaNotificacion:'', fr);\n    console.log(''fechaResolucionFirme:'', frf);\n    \n    if (!fn || !frf) {\n        console.log(''⚠️ Alguna fecha no existe, saltando validación'');\n        return {\n            valido: true,\n            error: null,\n            fechaResolucion: fr,\n            fechaNotificacion: fn,\n            fechaResolucionFirme: frf,\n            fechaNotificacionFirme: fnf,\n            fechaEjecucion: fes\n        };\n    }\n    \n    const timestampFN = new Date(fn).getTime();\n    const timestampFRF = new Date(frf).getTime();\n    \n    console.log(''Timestamp FN:'', timestampFN);\n    console.log(''Timestamp FRF:'', timestampFRF);\n    \n    const valido = timestampFRF >= timestampFN;\n    console.log(''¿Es válido (FRF >= FN)?:'', valido);\n    \n    if (!valido) {\n        console.log(''❌ VALIDACIÓN FALLIDA'');\n        throw new Error(''La Fecha de Resolución Firme no puede ser anterior a la Fecha de Notifación de la Resolución'');\n    }\n    \n    console.log(''✅ VALIDACIÓN EXITOSA'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', '564c17c9-54e2-4462-9348-4c552d06fd07', NULL, 'd5fdb86f-1a1b-4828-be82-f046907940ba', '2025-11-26 00:12:45.345+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d67af58b-8786-465a-9d68-27d0cccf6b5f', 'valida fecha resolución firme', 'valida_fnf', 'exec', 39, 39, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== VALIDACIÓN 2: fechaResolucionFirme >= fechaNotificacion ==='');\n    \n    const fr = data.extraer_fechas.fechaResolucion;\n    const fn = data.extraer_fechas.fechaNotificacion;\n    const frf = data.extraer_fechas.fechaResolucionFirme;\n    const fnf = data.extraer_fechas.fechaNotificacionFirme;\n    const fes = data.extraer_fechas.fechaEjecucion;\n    \n    console.log(''fechaNotificacion:'', fr);\n    console.log(''fechaResolucionFirme:'', frf);\n    \n    if (!fn || !frf) {\n        console.log(''⚠️ Alguna fecha no existe, saltando validación'');\n        return {\n            valido: true,\n            error: null,\n            fechaResolucion: fr,\n            fechaNotificacion: fn,\n            fechaResolucionFirme: frf,\n            fechaNotificacionFirme: fnf,\n            fechaEjecucion: fes\n        };\n    }\n    \n    const timestampFN = new Date(fn).getTime();\n    const timestampFRF = new Date(frf).getTime();\n    \n    console.log(''Timestamp FN:'', timestampFN);\n    console.log(''Timestamp FRF:'', timestampFRF);\n    \n    const valido = timestampFRF >= timestampFN;\n    console.log(''¿Es válido (FRF >= FN)?:'', valido);\n    \n    if (!valido) {\n        console.log(''❌ VALIDACIÓN FALLIDA'');\n        throw new Error(''La Fecha de Resolución Firme no puede ser anterior a la Fecha de Notifación de la Resolución'');\n    }\n    \n    console.log(''✅ VALIDACIÓN EXITOSA'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', 'e19fea3b-a502-4a0d-bd0d-0e2aa9b7cf44', NULL, 'b0798b97-4e5f-42c5-8633-e1758caf7125', '2025-11-24 00:03:13.615+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a4ba905d-e827-41f1-b28d-2ff231a9aeed', 'valida fecha notificacion', 'valida_fn', 'exec', 21, 39, '{"code":"module.exports = async function(data) {\n    console.log(''VALIDACIÓN 1: fechaNotificacion >= fechaResolucion'');\n    \n    // Usar la key específica del paso anterior\n    const fr = data.extraer_fechas.fechaResolucion;\n    const fn = data.extraer_fechas.fechaNotificacion;\n    const frf = data.extraer_fechas.fechaResolucionFirme;\n    const fnf = data.extraer_fechas.fechaNotificacionFirme;\n    const fes = data.extraer_fechas.fechaEjecucion;\n    \n    console.log(''fechaResolucion:'', fr);\n    console.log(''fechaNotificacion:'', fn);\n    \n    if (!fr || !fn) {\n        console.log(''⚠️ Alguna fecha no existe, saltando validación'');\n        return {\n            valido: true,\n            error: null,\n            fechaResolucion: fr,\n            fechaNotificacion: fn,\n            fechaResolucionFirme: frf,\n            fechaNotificacionFirme: fnf,\n            fechaEjecucion: fes\n        };\n    }\n    \n    // Convertir a timestamps para comparar\n    const timestampFR = new Date(fr).getTime();\n    const timestampFN = new Date(fn).getTime();\n    \n    console.log(''Timestamp FR:'', timestampFR);\n    console.log(''Timestamp FN:'', timestampFN);\n    \n    // Validar: fechaNotificacion >= fechaResolucion\n    const valido = timestampFN >= timestampFR;\n    console.log(''¿Es válido (FN >= FR)?:'', valido);\n    \n    if (!valido) {\n        console.log(''❌ VALIDACIÓN FALLIDA'');\n        throw new Error(''La Fecha de Notificación no puede ser anterior a la Fecha de Resolución'');\n    }\n    \n    console.log(''✅ VALIDACIÓN EXITOSA'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', 'd67af58b-8786-465a-9d68-27d0cccf6b5f', NULL, 'b0798b97-4e5f-42c5-8633-e1758caf7125', '2025-11-19 22:44:35.556+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a439b561-e5ca-4c49-a2d1-f8556bcd09b2', 'extraer fechas', 'extraer_fechas', 'exec', 39, 19, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== EXTRAER Y COMBINAR FECHAS ==='');\n    \n    const trigger = data.$trigger;\n    const payload = trigger.payload;\n    const event = trigger.event;\n    \n    console.log(''Event:'', event);\n    console.log(''Payload resolucion:'', JSON.stringify(payload.resolucion, null, 2));\n    \n    let resolucionFinal;\n    \n    // En CREATE: todo viene del payload, no hay datos en BD\n    if (event.includes(''create'')) {\n        console.log(''📝 CREATE: usando datos del payload'');\n        resolucionFinal = payload.resolucion;\n        \n        if (!resolucionFinal || typeof resolucionFinal !== ''object'') {\n            console.log(''⏭️ No hay datos de resolución en CREATE'');\n            return { skip: true };\n        }\n    }\n    // En UPDATE: combinar BD + payload\n    else if (event.includes(''update'')) {\n        console.log(''📝 UPDATE: combinando BD + payload'');\n        \n        const registros = data.leer_registro || [];\n        const recordId = trigger.keys?.[0];\n        const registro = registros.find(r => r.id === recordId) || registros[0];\n        \n        console.log(''Record ID:'', recordId);\n        console.log(''Registro encontrado:'', registro?.id);\n        \n        let resolucionBD = registro?.resolucion;\n        \n        if (!resolucionBD || typeof resolucionBD !== ''object'') {\n            console.log(''⏭️ No hay datos de resolución en BD'');\n            return { skip: true };\n        }\n        \n        // Combinar: BD + cambios del payload\n        resolucionFinal = { ...resolucionBD };\n        \n        if (payload.resolucion && typeof payload.resolucion === ''object'') {\n            console.log(''🔄 Aplicando cambios del payload sobre BD'');\n            resolucionFinal = {\n                ...resolucionBD,\n                ...payload.resolucion\n            };\n        }\n    }\n    \n    console.log(''Resolución final:'', JSON.stringify(resolucionFinal, null, 2));\n    \n    const fechas = {\n        fechaResolucion: resolucionFinal.fechaResolucion,\n        fechaNotificacion: resolucionFinal.fechaNotificacion,\n        fechaResolucionFirme: resolucionFinal.fechaResolucionFirme,\n        fechaNotificacionFirme: resolucionFinal.fechaNotificacionFirme,\n        fechaEjecucion: resolucionFinal.fechaEjecucion\n    };\n    \n    console.log(''✅ Fechas extraídas:'', fechas);\n    \n    return fechas;\n};"}', 'a4ba905d-e827-41f1-b28d-2ff231a9aeed', NULL, 'b0798b97-4e5f-42c5-8633-e1758caf7125', '2025-11-19 22:33:11.211+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1d010568-0bdf-4ca6-aa60-a272c497676a', 'valida fecha resolución firme', 'valida_fnf', 'exec', 38, 19, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== VALIDACIÓN 2: fechaResolucionFirme >= fechaNotificacion ==='');\n    \n    const fr = data.extraer_fechas.fechaResolucion;\n    const fn = data.extraer_fechas.fechaNotificacion;\n    const frf = data.extraer_fechas.fechaResolucionFirme;\n    const fnf = data.extraer_fechas.fechaNotificacionFirme;\n    const fes = data.extraer_fechas.fechaEjecucion;\n    \n    console.log(''fechaNotificacion:'', fr);\n    console.log(''fechaResolucionFirme:'', frf);\n    \n    if (!fn || !frf) {\n        console.log(''⚠️ Alguna fecha no existe, saltando validación'');\n        return {\n            valido: true,\n            error: null,\n            fechaResolucion: fr,\n            fechaNotificacion: fn,\n            fechaResolucionFirme: frf,\n            fechaNotificacionFirme: fnf,\n            fechaEjecucion: fes\n        };\n    }\n    \n    const timestampFN = new Date(fn).getTime();\n    const timestampFRF = new Date(frf).getTime();\n    \n    console.log(''Timestamp FN:'', timestampFN);\n    console.log(''Timestamp FRF:'', timestampFRF);\n    \n    const valido = timestampFRF >= timestampFN;\n    console.log(''¿Es válido (FRF >= FN)?:'', valido);\n    \n    if (!valido) {\n        console.log(''❌ VALIDACIÓN FALLIDA'');\n        throw new Error(''La Fecha de Resolución Firme no puede ser anterior a la Fecha de Notifación de la Resolución'');\n    }\n    \n    console.log(''✅ VALIDACIÓN EXITOSA'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', 'cc3ed2f4-fd6b-46bc-ac3c-126d6096ee4e', NULL, '6f1a5ebe-b90c-4b7e-b9f2-6449c29ea743', '2025-11-26 00:17:26.508+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('74a3ce53-ccc3-42bd-a3dc-e864f62d2d9b', 'extraer fechas', 'extraer_fechas', 'exec', 56, 1, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== EXTRAER Y COMBINAR FECHAS ==='');\n    \n    const trigger = data.$trigger;\n    const payload = trigger.payload;\n    const event = trigger.event;\n    \n    console.log(''Event:'', event);\n    console.log(''Payload resolucion:'', JSON.stringify(payload.resolucion, null, 2));\n    \n    let resolucionFinal;\n    \n    // En CREATE: todo viene del payload, no hay datos en BD\n    if (event.includes(''create'')) {\n        console.log(''📝 CREATE: usando datos del payload'');\n        resolucionFinal = payload.resolucion;\n        \n        if (!resolucionFinal || typeof resolucionFinal !== ''object'') {\n            console.log(''⏭️ No hay datos de resolución en CREATE'');\n            return { skip: true };\n        }\n    }\n    // En UPDATE: combinar BD + payload\n    else if (event.includes(''update'')) {\n        console.log(''📝 UPDATE: combinando BD + payload'');\n        \n        const registros = data.leer_registro || [];\n        const recordId = trigger.keys?.[0];\n        const registro = registros.find(r => r.id === recordId) || registros[0];\n        \n        console.log(''Record ID:'', recordId);\n        console.log(''Registro encontrado:'', registro?.id);\n        \n        let resolucionBD = registro?.resolucion;\n        \n        if (!resolucionBD || typeof resolucionBD !== ''object'') {\n            console.log(''⏭️ No hay datos de resolución en BD'');\n            return { skip: true };\n        }\n        \n        // Combinar: BD + cambios del payload\n        resolucionFinal = { ...resolucionBD };\n        \n        if (payload.resolucion && typeof payload.resolucion === ''object'') {\n            console.log(''🔄 Aplicando cambios del payload sobre BD'');\n            resolucionFinal = {\n                ...resolucionBD,\n                ...payload.resolucion\n            };\n        }\n    }\n    \n    console.log(''Resolución final:'', JSON.stringify(resolucionFinal, null, 2));\n    \n    const fechas = {\n        fechaResolucion: resolucionFinal.fechaResolucion,\n        fechaNotificacion: resolucionFinal.fechaNotificacion,\n        fechaResolucionFirme: resolucionFinal.fechaResolucionFirme,\n        fechaNotificacionFirme: resolucionFinal.fechaNotificacionFirme,\n        fechaEjecucion: resolucionFinal.fechaEjecucion\n    };\n    \n    console.log(''✅ Fechas extraídas:'', fechas);\n    \n    return fechas;\n};"}', 'fee812f9-6d0b-491a-be57-b1387ca3d82c', NULL, 'cf3855aa-ca21-4544-a1f7-ee3351d274cc', '2025-11-26 00:06:47.637+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5d1fb67c-9169-4b4b-b83c-150a5f3b9930', 'extraer fechas', 'extraer_fechas', 'exec', 56, 1, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== EXTRAER Y COMBINAR FECHAS ==='');\n    \n    const trigger = data.$trigger;\n    const payload = trigger.payload;\n    const event = trigger.event;\n    \n    console.log(''Event:'', event);\n    console.log(''Payload resolucion:'', JSON.stringify(payload.resolucion, null, 2));\n    \n    let resolucionFinal;\n    \n    // En CREATE: todo viene del payload, no hay datos en BD\n    if (event.includes(''create'')) {\n        console.log(''📝 CREATE: usando datos del payload'');\n        resolucionFinal = payload.resolucion;\n        \n        if (!resolucionFinal || typeof resolucionFinal !== ''object'') {\n            console.log(''⏭️ No hay datos de resolución en CREATE'');\n            return { skip: true };\n        }\n    }\n    // En UPDATE: combinar BD + payload\n    else if (event.includes(''update'')) {\n        console.log(''📝 UPDATE: combinando BD + payload'');\n        \n        const registros = data.leer_registro || [];\n        const recordId = trigger.keys?.[0];\n        const registro = registros.find(r => r.id === recordId) || registros[0];\n        \n        console.log(''Record ID:'', recordId);\n        console.log(''Registro encontrado:'', registro?.id);\n        \n        let resolucionBD = registro?.resolucion;\n        \n        if (!resolucionBD || typeof resolucionBD !== ''object'') {\n            console.log(''⏭️ No hay datos de resolución en BD'');\n            return { skip: true };\n        }\n        \n        // Combinar: BD + cambios del payload\n        resolucionFinal = { ...resolucionBD };\n        \n        if (payload.resolucion && typeof payload.resolucion === ''object'') {\n            console.log(''🔄 Aplicando cambios del payload sobre BD'');\n            resolucionFinal = {\n                ...resolucionBD,\n                ...payload.resolucion\n            };\n        }\n    }\n    \n    console.log(''Resolución final:'', JSON.stringify(resolucionFinal, null, 2));\n    \n    const fechas = {\n        fechaResolucion: resolucionFinal.fechaResolucion,\n        fechaNotificacion: resolucionFinal.fechaNotificacion,\n        fechaResolucionFirme: resolucionFinal.fechaResolucionFirme,\n        fechaNotificacionFirme: resolucionFinal.fechaNotificacionFirme,\n        fechaEjecucion: resolucionFinal.fechaEjecucion\n    };\n    \n    console.log(''✅ Fechas extraídas:'', fechas);\n    \n    return fechas;\n};"}', '58191d4d-9d62-45c6-87cb-4e06ea2ef5d8', NULL, '6f1a5ebe-b90c-4b7e-b9f2-6449c29ea743', '2025-11-26 00:17:19.464+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1b3d355a-4700-44b2-952d-31e70d8aaa46', 'Leer datos', 'item_read_l0igv_fuavu', 'item-read', 63, 35, '{"collection":"{{$trigger.collection}}","query":{"filter":{"_and":[{"expediente":{"_eq":"{{ datosUnificados_apbqe.expediente }}"}}]},"fields":["id","expediente","datosGenerales.curp","datosGenerales.rfc"]}}', '8524fa2f-25f1-4500-a9b4-d442cf437772', NULL, '77777777-7777-7777-7777-777777777777', '2025-11-26 19:58:12.851+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a3b82f03-303b-48ea-a1d8-b5470944123c', 'imprimir logs', 'imprimir_logs', 'log', 19, 1, '{"message":"{{$trigger.payload}}"}', '06835738-20ee-4ea8-b464-74beccb0febf', NULL, '1a474ecf-995d-4049-bb7d-cef1b4ae8da9', '2025-11-27 17:51:01.63+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('06835738-20ee-4ea8-b464-74beccb0febf', 'validar datos', 'validar_datos', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const payload = data.$trigger?.payload || {};\n    const event = data.$trigger?.event || '''';\n    \n    console.log(''=== EVENTO ==='', event);\n    console.log(''=== PAYLOAD ==='', JSON.stringify(payload, null, 2));\n    \n    // Filtrar solo eventos de representante individual\n    if (event === ''datos_representante.items.update'') {\n        console.log(''⚠️ Saltando validación - Evento no relevante'');\n        return data;\n    }\n    \n    const nameRegex = /^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ\\s''-]+$/;\n    const errores = [];\n    \n    const validarCampo = (valor, nombreCampo) => {\n        if (!valor || valor.trim() === '''') return;\n        \n        if (!nameRegex.test(valor)) {\n            const invalidChars = [...new Set(\n                valor.match(/[^A-Za-zÁÉÍÓÚÜÑáéíóúüñ\\s''-]/g)\n            )];\n            errores.push(`${nombreCampo} (${invalidChars.join(\", \")})`);\n        }\n    };\n    \n    // Detectar de dónde vienen los datos según la estructura\n    let directorGeneral, representanteLegal;\n    \n    if (payload.datosDirGeneralReprLegal) {\n        // Viene de faltas_graves_personas_morales\n        directorGeneral = payload.datosDirGeneralReprLegal.directorGeneral || {};\n        representanteLegal = payload.datosDirGeneralReprLegal.representanteLegal || {};\n    } else if (payload.directorGeneral || payload.representanteLegal) {\n        // Viene de datos_dg_rp (puede tener uno o ambos)\n        directorGeneral = payload.directorGeneral || {};\n        representanteLegal = payload.representanteLegal || {};\n    } else {\n        console.log(''⚠️ Estructura no reconocida'');\n        return data;\n    }\n    \n    // Validar Director General (si existe)\n    if (directorGeneral.nombre || directorGeneral.primerApellido || directorGeneral.segundoApellido) {\n        validarCampo(directorGeneral.nombre, ''Nombre del Director General'');\n        validarCampo(directorGeneral.primerApellido, ''Primer Apellido del Director General'');\n        validarCampo(directorGeneral.segundoApellido, ''Segundo Apellido del Director General'');\n    }\n    \n    // Validar Representante Legal (si existe)\n    if (representanteLegal.nombre || representanteLegal.primerApellido || representanteLegal.segundoApellido) {\n        validarCampo(representanteLegal.nombre, ''Nombre del Representante Legal'');\n        validarCampo(representanteLegal.primerApellido, ''Primer Apellido del Representante Legal'');\n        validarCampo(representanteLegal.segundoApellido, ''Segundo Apellido del Representante Legal'');\n    }\n    \n    // Lanzar error con todos los campos inválidos\n    if (errores.length > 0) {\n        throw new Error(\n            `Se encontraron caracteres no permitidos en los siguientes campos: ${errores.join('' | '')}. ` +\n            `Solo se aceptan letras del alfabeto latino, Ñ/ñ, Ü/ü, espacios, guiones y apóstrofes`\n        );\n    }\n    \n    console.log(''✅ Validación exitosa'');\n    return data;\n};"}', NULL, NULL, '1a474ecf-995d-4049-bb7d-cef1b4ae8da9', '2025-11-27 17:51:05.896+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2d409805-905e-4529-88db-def2dbef52f1', 'Ejecutar script', 'exec_17h3t', 'exec', 85, 18, '{"code":"module.exports = async function (data) {\n  const lista = Array.isArray(data.$last) ? data.$last : [];\n\n  const {\n    curp,\n    rfc,\n    expediente,\n    esUpdate,\n    idOriginal\n  } = data.datosUnificados || {};\n\n  console.log(\"VALIDANDO:\", { curp, rfc, expediente, esUpdate, idOriginal, lista });\n\n  const duplicado = lista.find((item) => {\n    const coincidePersona =\n      item.datosGenerales?.curp === curp &&\n      item.datosGenerales?.rfc === rfc;\n\n    const coincideExpediente =\n      item.expediente === expediente;\n\n    // En update: excluirse a sí mismo\n    const noEsElMismo = !esUpdate || item.id !== idOriginal;\n\n    return coincidePersona && coincideExpediente && noEsElMismo;\n  });\n\n  if (duplicado) {\n    const err = new Error(\n      \"⚠ Ya existe una sanción con la misma persona (CURP/RFC) y el mismo expediente.\"\n    );\n    err.status = 400;\n    throw err;\n  }\n\n  return { ok: true };\n};\n"}', NULL, NULL, '77777777-7777-7777-7777-777777777777', '2025-11-21 00:08:26.643+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1974daa8-257d-4d6f-92ea-26bef2236098', 'leer', 'datosUnificados_apbqe', 'exec', 47, 35, '{"code":"module.exports = async function (data) {\n  const trigger = data.$trigger || {};\n  const payload = trigger.payload || {};\n  const payloadDG = payload.datosGenerales || {};\n\n  const reg = Array.isArray(data.$last) && data.$last.length > 0\n    ? data.$last[0]\n    : {};\n\n  const dbDG = reg.datosGenerales || {};\n\n  // --- Unificación para UPDATE ó CREATE ---\n  const curp = payloadDG.curp || dbDG.curp || null;\n  const rfc = payloadDG.rfc || dbDG.rfc || null;\n  const expediente = payload.expediente || reg.expediente || null;\n\n  console.log(\"🔍 UNIFICADO:\", { curp, rfc, expediente });\n\n  return {\n    curp,\n    rfc,\n    expediente,\n    esUpdate: !!trigger.keys?.length, // <--- CLAVE PARA SIGUIENTE PASO\n    idOriginal: trigger.keys?.[0] || null\n  };\n};"}', '1b3d355a-4700-44b2-952d-31e70d8aaa46', NULL, '77777777-7777-7777-7777-777777777777', '2025-11-26 19:58:12.862+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4bb4b103-47b8-4e8b-a01e-a2c108e0886d', 'Leer datos', 'leer_registro', 'item-read', 21, 19, '{"collection":"faltas_administrativas_graves","query":{"keys":["{{$trigger.keys[0]}}"],"fields":["*","resolucion.*"]}}', 'a439b561-e5ca-4c49-a2d1-f8556bcd09b2', NULL, 'b0798b97-4e5f-42c5-8633-e1758caf7125', '2025-11-25 18:34:23.86+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6f6906de-6c35-4f2c-9433-ae35ab11fcf4', 'imprimir payload', 'imprimir_payload', 'exec', 3, 19, '{"code":"module.exports = async function(data) {\n    console.log(''Payload:'', data.$trigger.payload);\n    return data;\n};"}', '4bb4b103-47b8-4e8b-a01e-a2c108e0886d', NULL, 'b0798b97-4e5f-42c5-8633-e1758caf7125', '2025-11-19 18:36:55.362+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('58191d4d-9d62-45c6-87cb-4e06ea2ef5d8', 'valida fecha notificacion', 'valida_fn', 'exec', 20, 19, '{"code":"module.exports = async function(data) {\n    console.log(''VALIDACIÓN 1: fechaNotificacion >= fechaResolucion'');\n    \n    // Usar la key específica del paso anterior\n    const fr = data.extraer_fechas.fechaResolucion;\n    const fn = data.extraer_fechas.fechaNotificacion;\n    const frf = data.extraer_fechas.fechaResolucionFirme;\n    const fnf = data.extraer_fechas.fechaNotificacionFirme;\n    const fes = data.extraer_fechas.fechaEjecucion;\n    \n    console.log(''fechaResolucion:'', fr);\n    console.log(''fechaNotificacion:'', fn);\n    \n    if (!fr || !fn) {\n        console.log(''⚠️ Alguna fecha no existe, saltando validación'');\n        return {\n            valido: true,\n            error: null,\n            fechaResolucion: fr,\n            fechaNotificacion: fn,\n            fechaResolucionFirme: frf,\n            fechaNotificacionFirme: fnf,\n            fechaEjecucion: fes\n        };\n    }\n    \n    // Convertir a timestamps para comparar\n    const timestampFR = new Date(fr).getTime();\n    const timestampFN = new Date(fn).getTime();\n    \n    console.log(''Timestamp FR:'', timestampFR);\n    console.log(''Timestamp FN:'', timestampFN);\n    \n    // Validar: fechaNotificacion >= fechaResolucion\n    const valido = timestampFN >= timestampFR;\n    console.log(''¿Es válido (FN >= FR)?:'', valido);\n    \n    if (!valido) {\n        console.log(''❌ VALIDACIÓN FALLIDA'');\n        throw new Error(''La Fecha de Notificación no puede ser anterior a la Fecha de Resolución'');\n    }\n    \n    console.log(''✅ VALIDACIÓN EXITOSA'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', '1d010568-0bdf-4ca6-aa60-a272c497676a', NULL, '6f1a5ebe-b90c-4b7e-b9f2-6449c29ea743', '2025-11-26 00:17:23.559+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b76677f3-68d6-45e4-9195-8dd68b6ee280', 'imprimir payload', 'imprimir_payload', 'exec', 20, 1, '{"code":"module.exports = async function(data) {\n    console.log(''Payload:'', data.$trigger.payload);\n    return data;\n};"}', '57034de1-83b5-4e72-9095-03354a08f10c', NULL, '6f1a5ebe-b90c-4b7e-b9f2-6449c29ea743', '2025-11-26 00:17:08.657+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('cc3a6a16-8cb0-48b9-9125-204b2b344863', 'validacion fecha notificación firme', 'valida_frf', 'exec', 56, 19, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== VALIDACIÓN 3: fechaNotificacionFirme >= fechaResolucionFirme Y fechaEjecucion >= fechaNotificacionFirme ==='');\n    \n    const fr = data.$last.fechaResolucion;\n    const fn = data.$last.fechaNotificacion;\n    const frf = data.$last.fechaResolucionFirme;\n    const fnf = data.$last.fechaNotificacionFirme;\n    const fes = data.$last.fechaEjecucion;\n    \n    console.log(''fechaResolucionFirme:'', frf);\n    console.log(''fechaNotificacionFirme:'', fnf);\n    console.log(''fechaEjecucion:'', fes);\n    \n    // Validación 1: FNF >= FRF\n    if (fnf && frf) {\n        const timestampFNF = new Date(fnf).getTime();\n        const timestampFRF = new Date(frf).getTime();\n        \n        console.log(''Timestamp FNF:'', timestampFNF);\n        console.log(''Timestamp FRF:'', timestampFRF);\n        \n        const validoFNF = timestampFNF >= timestampFRF;\n        console.log(''¿Es válido (FNF >= FRF)?:'', validoFNF);\n        \n        if (!validoFNF) {\n            console.log(''❌ VALIDACIÓN 1 FALLIDA'');\n            throw new Error(''La Fecha de Notificación de la Resolución Firme no puede ser anterior a la Fecha de la Resolución Firme'');\n        }\n        \n        console.log(''✅ VALIDACIÓN 1 EXITOSA (FNF >= FRF)'');\n    } else {\n        console.log(''⚠️ FNF o FRF no existe, saltando validación 1'');\n    }\n    \n    // Validación 2: FES >= FNF\n    if (fes && fnf) {\n        const timestampFES = new Date(fes).getTime();\n        const timestampFNF = new Date(fnf).getTime();\n        \n        console.log(''Timestamp FES:'', timestampFES);\n        console.log(''Timestamp FNF:'', timestampFNF);\n        \n        const validoFES = timestampFES >= timestampFNF;\n        console.log(''¿Es válido (FES >= FNF)?:'', validoFES);\n        \n        if (!validoFES) {\n            console.log(''❌ VALIDACIÓN 2 FALLIDA'');\n            throw new Error(''La Fecha de Ejecución no puede ser anterior a la Fecha de Notificación Firme'');\n        }\n        \n        console.log(''✅ VALIDACIÓN 2 EXITOSA (FES >= FNF)'');\n    } else {\n        console.log(''⚠️ FES o FNF no existe, saltando validación 2'');\n    }\n    \n    console.log(''✅ TODAS LAS VALIDACIONES DEL PASO COMPLETADAS'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', NULL, NULL, 'cf3855aa-ca21-4544-a1f7-ee3351d274cc', '2025-11-26 00:07:21.11+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('fee812f9-6d0b-491a-be57-b1387ca3d82c', 'valida fecha notificacion', 'valida_fn', 'exec', 20, 19, '{"code":"module.exports = async function(data) {\n    console.log(''VALIDACIÓN 1: fechaNotificacion >= fechaResolucion'');\n    \n    // Usar la key específica del paso anterior\n    const fr = data.extraer_fechas.fechaResolucion;\n    const fn = data.extraer_fechas.fechaNotificacion;\n    const frf = data.extraer_fechas.fechaResolucionFirme;\n    const fnf = data.extraer_fechas.fechaNotificacionFirme;\n    const fes = data.extraer_fechas.fechaEjecucion;\n    \n    console.log(''fechaResolucion:'', fr);\n    console.log(''fechaNotificacion:'', fn);\n    \n    if (!fr || !fn) {\n        console.log(''⚠️ Alguna fecha no existe, saltando validación'');\n        return {\n            valido: true,\n            error: null,\n            fechaResolucion: fr,\n            fechaNotificacion: fn,\n            fechaResolucionFirme: frf,\n            fechaNotificacionFirme: fnf,\n            fechaEjecucion: fes\n        };\n    }\n    \n    // Convertir a timestamps para comparar\n    const timestampFR = new Date(fr).getTime();\n    const timestampFN = new Date(fn).getTime();\n    \n    console.log(''Timestamp FR:'', timestampFR);\n    console.log(''Timestamp FN:'', timestampFN);\n    \n    // Validar: fechaNotificacion >= fechaResolucion\n    const valido = timestampFN >= timestampFR;\n    console.log(''¿Es válido (FN >= FR)?:'', valido);\n    \n    if (!valido) {\n        console.log(''❌ VALIDACIÓN FALLIDA'');\n        throw new Error(''La Fecha de Notificación no puede ser anterior a la Fecha de Resolución'');\n    }\n    \n    console.log(''✅ VALIDACIÓN EXITOSA'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', '2f607212-ed54-4bac-880e-5bcd00c6a3e9', NULL, 'cf3855aa-ca21-4544-a1f7-ee3351d274cc', '2025-11-26 00:07:12.322+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('acee4f70-1a46-42c3-bbee-9b5c73af537e', 'imprimir payload', 'imprimir_payload', 'exec', 20, 1, '{"code":"module.exports = async function(data) {\n    console.log(''Payload:'', data.$trigger.payload);\n    return data;\n};"}', '58bb2108-6d3a-4079-9d9f-29802bce74ab', NULL, 'cf3855aa-ca21-4544-a1f7-ee3351d274cc', '2025-11-26 00:04:30.254+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('016abf21-7569-49c6-85c4-421d4aab858e', 'Ejecutar script', 'exec_nqu74', 'exec', 18, 1, '{"code":"module.exports = async function(data) {\n  const keys = data.$trigger.keys || data.$trigger.key;\n\n  let id_final;\n\n  if (Array.isArray(keys)) {\n    // Si es arreglo, tomamos el primero\n    id_final = keys[0];\n  } else {\n    // Si ya es string o algo similar\n    id_final = String(keys);\n  }\n\n  return {\n    id_final\n  };\n};\n"}', '3c6832c1-a459-4721-a8da-7a221720ecde', NULL, '4c039908-6256-4d97-8f14-71b8532898cc', '2025-11-19 23:56:44.677+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('fa7103dc-a66f-48d9-a453-0cff58b06681', 'Registrar en la consola', 'log_pqe1y', 'log', 72, 17, '{"message":"{{inicialesEsperadasU}}"}', 'e62e97b6-719b-4839-a3f0-65b84a32b00b', NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 17:31:03.652+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('20148677-02df-4876-8fbd-e77da990c057', 'Leer datos', 'item_read_l0igv', 'item-read', 68, 18, '{"collection":"{{$trigger.collection}}","query":{"filter":{"_and":[{"expediente":{"_eq":"{{ datosUnificados.expediente }}"}}]},"fields":["id","expediente","datosGenerales.curp","datosGenerales.rfc"]}}', '2d409805-905e-4529-88db-def2dbef52f1', NULL, '77777777-7777-7777-7777-777777777777', '2025-11-21 00:06:34.172+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4930d1a0-69e4-4ec7-85fc-365b7a08ee80', 'leer', 'datosUnificados', 'exec', 52, 18, '{"code":"module.exports = async function (data) {\n  const trigger = data.$trigger || {};\n  const payload = trigger.payload || {};\n  const payloadDG = payload.datosGenerales || {};\n\n  const reg = Array.isArray(data.$last) && data.$last.length > 0\n    ? data.$last[0]\n    : {};\n\n  const dbDG = reg.datosGenerales || {};\n\n  // --- Unificación para UPDATE ó CREATE ---\n  const curp = payloadDG.curp || dbDG.curp || null;\n  const rfc = payloadDG.rfc || dbDG.rfc || null;\n  const expediente = payload.expediente || reg.expediente || null;\n\n  console.log(\"🔍 UNIFICADO:\", { curp, rfc, expediente });\n\n  return {\n    curp,\n    rfc,\n    expediente,\n    esUpdate: !!trigger.keys?.length, // <--- CLAVE PARA SIGUIENTE PASO\n    idOriginal: trigger.keys?.[0] || null\n  };\n};"}', '20148677-02df-4876-8fbd-e77da990c057', NULL, '77777777-7777-7777-7777-777777777777', '2025-11-05 00:41:31.078+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b7e8dc0e-a475-4338-a7ba-4ad090ddc4e8', 'Ejecutar script', 'registroActual', 'item-read', 36, 18, '{"collection":"{{$trigger.collection}}","query":{"filter":{"id":{"_eq":"{{ exec_eegtp.idOriginal  }}"}},"fields":["id","expediente","datosGenerales.id","datosGenerales.curp","datosGenerales.rfc"],"limit":50}}', '4930d1a0-69e4-4ec7-85fc-365b7a08ee80', NULL, '77777777-7777-7777-7777-777777777777', '2025-11-05 00:37:52.353+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('fd09eeda-f4b0-42a0-b77d-b2b5058eeb5a', 'Actualizar datos', 'item_update_5yczv', 'item-update', 66, 1, '{"collection":"{{$trigger.collection}}","payload":{"busqueda_personalizada":"{{exec_xikiw}}"},"query":{"filter":{"id":{"_eq":"{{exec_nqu74.id_final}}"}}}}', NULL, NULL, '4c039908-6256-4d97-8f14-71b8532898cc', '2025-11-19 23:31:53.03+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3c6832c1-a459-4721-a8da-7a221720ecde', 'Leer datos', 'item_read_8v1ol', 'item-read', 34, 1, '{"collection":"{{$trigger.collection}}","query":{"filter":{"id":{"_eq":"{{$last.id_final}}"}},"fields":["id","datosGenerales.id","datosGenerales.nombres","datosGenerales.primerApellido","datosGenerales.segundoApellido","datosGenerales.rfc","datosGenerales.curp","expediente","datosGenerales.nombreRazonSocial"],"limit":1}}', '5f1bc1bc-acad-4579-9a06-0c3c5f7996e4', NULL, '4c039908-6256-4d97-8f14-71b8532898cc', '2025-11-19 23:31:53.06+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7db48e3c-e534-4882-8e45-490656799ce6', 'valida fecha notificacion', 'valida_fn', 'exec', 20, 19, '{"code":"module.exports = async function(data) {\n    console.log(''VALIDACIÓN 1: fechaNotificacion >= fechaResolucion'');\n    \n    // Usar la key específica del paso anterior\n    const fr = data.extraer_fechas.fechaResolucion;\n    const fn = data.extraer_fechas.fechaNotificacion;\n    const frf = data.extraer_fechas.fechaResolucionFirme;\n    const fnf = data.extraer_fechas.fechaNotificacionFirme;\n    const fes = data.extraer_fechas.fechaEjecucion;\n    \n    console.log(''fechaResolucion:'', fr);\n    console.log(''fechaNotificacion:'', fn);\n    \n    if (!fr || !fn) {\n        console.log(''⚠️ Alguna fecha no existe, saltando validación'');\n        return {\n            valido: true,\n            error: null,\n            fechaResolucion: fr,\n            fechaNotificacion: fn,\n            fechaResolucionFirme: frf,\n            fechaNotificacionFirme: fnf,\n            fechaEjecucion: fes\n        };\n    }\n    \n    // Convertir a timestamps para comparar\n    const timestampFR = new Date(fr).getTime();\n    const timestampFN = new Date(fn).getTime();\n    \n    console.log(''Timestamp FR:'', timestampFR);\n    console.log(''Timestamp FN:'', timestampFN);\n    \n    // Validar: fechaNotificacion >= fechaResolucion\n    const valido = timestampFN >= timestampFR;\n    console.log(''¿Es válido (FN >= FR)?:'', valido);\n    \n    if (!valido) {\n        console.log(''❌ VALIDACIÓN FALLIDA'');\n        throw new Error(''La Fecha de Notificación no puede ser anterior a la Fecha de Resolución'');\n    }\n    \n    console.log(''✅ VALIDACIÓN EXITOSA'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', 'dc848ba6-e7c4-4a95-8b06-92681974ee08', NULL, 'd5fdb86f-1a1b-4828-be82-f046907940ba', '2025-11-26 00:12:42.919+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7b92bb08-e3e2-4e87-b3fd-4f65adfdb3d8', 'extraer fechas', 'extraer_fechas', 'exec', 56, 1, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== EXTRAER Y COMBINAR FECHAS ==='');\n    \n    const trigger = data.$trigger;\n    const payload = trigger.payload;\n    const event = trigger.event;\n    \n    console.log(''Event:'', event);\n    console.log(''Payload resolucion:'', JSON.stringify(payload.resolucion, null, 2));\n    \n    let resolucionFinal;\n    \n    // En CREATE: todo viene del payload, no hay datos en BD\n    if (event.includes(''create'')) {\n        console.log(''📝 CREATE: usando datos del payload'');\n        resolucionFinal = payload.resolucion;\n        \n        if (!resolucionFinal || typeof resolucionFinal !== ''object'') {\n            console.log(''⏭️ No hay datos de resolución en CREATE'');\n            return { skip: true };\n        }\n    }\n    // En UPDATE: combinar BD + payload\n    else if (event.includes(''update'')) {\n        console.log(''📝 UPDATE: combinando BD + payload'');\n        \n        const registros = data.leer_registro || [];\n        const recordId = trigger.keys?.[0];\n        const registro = registros.find(r => r.id === recordId) || registros[0];\n        \n        console.log(''Record ID:'', recordId);\n        console.log(''Registro encontrado:'', registro?.id);\n        \n        let resolucionBD = registro?.resolucion;\n        \n        if (!resolucionBD || typeof resolucionBD !== ''object'') {\n            console.log(''⏭️ No hay datos de resolución en BD'');\n            return { skip: true };\n        }\n        \n        // Combinar: BD + cambios del payload\n        resolucionFinal = { ...resolucionBD };\n        \n        if (payload.resolucion && typeof payload.resolucion === ''object'') {\n            console.log(''🔄 Aplicando cambios del payload sobre BD'');\n            resolucionFinal = {\n                ...resolucionBD,\n                ...payload.resolucion\n            };\n        }\n    }\n    \n    console.log(''Resolución final:'', JSON.stringify(resolucionFinal, null, 2));\n    \n    const fechas = {\n        fechaResolucion: resolucionFinal.fechaResolucion,\n        fechaNotificacion: resolucionFinal.fechaNotificacion,\n        fechaResolucionFirme: resolucionFinal.fechaResolucionFirme,\n        fechaNotificacionFirme: resolucionFinal.fechaNotificacionFirme,\n        fechaEjecucion: resolucionFinal.fechaEjecucion\n    };\n    \n    console.log(''✅ Fechas extraídas:'', fechas);\n    \n    return fechas;\n};"}', '7db48e3c-e534-4882-8e45-490656799ce6', NULL, 'd5fdb86f-1a1b-4828-be82-f046907940ba', '2025-11-26 00:12:39.922+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('28318875-b975-4360-9421-4989356a2d71', 'imprimir payload', 'imprimir_payload', 'exec', 20, 1, '{"code":"module.exports = async function(data) {\n    console.log(''Payload:'', data.$trigger.payload);\n    return data;\n};"}', 'be4a40ff-97e0-4519-bd14-2448ec8d0cb8', NULL, 'd5fdb86f-1a1b-4828-be82-f046907940ba', '2025-11-26 00:12:31.55+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('57034de1-83b5-4e72-9095-03354a08f10c', 'Leer datos', 'leer_registro', 'item-read', 38, 1, '{"collection":"datos_generales_personas_fisicas","query":{"keys":["{{$trigger.keys[0]}}"],"fields":["*","resolucion.*"]}}', '5d1fb67c-9169-4b4b-b83c-150a5f3b9930', NULL, '6f1a5ebe-b90c-4b7e-b9f2-6449c29ea743', '2025-11-26 00:17:12.422+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e19fea3b-a502-4a0d-bd0d-0e2aa9b7cf44', 'validacion fecha notificación firme', 'valida_frf', 'exec', 57, 39, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== VALIDACIÓN 3: fechaNotificacionFirme >= fechaResolucionFirme Y fechaEjecucion >= fechaNotificacionFirme ==='');\n    \n    const fr = data.$last.fechaResolucion;\n    const fn = data.$last.fechaNotificacion;\n    const frf = data.$last.fechaResolucionFirme;\n    const fnf = data.$last.fechaNotificacionFirme;\n    const fes = data.$last.fechaEjecucion;\n    \n    console.log(''fechaResolucionFirme:'', frf);\n    console.log(''fechaNotificacionFirme:'', fnf);\n    console.log(''fechaEjecucion:'', fes);\n    \n    // Validación 1: FNF >= FRF\n    if (fnf && frf) {\n        const timestampFNF = new Date(fnf).getTime();\n        const timestampFRF = new Date(frf).getTime();\n        \n        console.log(''Timestamp FNF:'', timestampFNF);\n        console.log(''Timestamp FRF:'', timestampFRF);\n        \n        const validoFNF = timestampFNF >= timestampFRF;\n        console.log(''¿Es válido (FNF >= FRF)?:'', validoFNF);\n        \n        if (!validoFNF) {\n            console.log(''❌ VALIDACIÓN 1 FALLIDA'');\n            throw new Error(''La Fecha de Notificación de la Resolución Firme no puede ser anterior a la Fecha de la Resolución Firme'');\n        }\n        \n        console.log(''✅ VALIDACIÓN 1 EXITOSA (FNF >= FRF)'');\n    } else {\n        console.log(''⚠️ FNF o FRF no existe, saltando validación 1'');\n    }\n    \n    // Validación 2: FES >= FNF\n    if (fes && fnf) {\n        const timestampFES = new Date(fes).getTime();\n        const timestampFNF = new Date(fnf).getTime();\n        \n        console.log(''Timestamp FES:'', timestampFES);\n        console.log(''Timestamp FNF:'', timestampFNF);\n        \n        const validoFES = timestampFES >= timestampFNF;\n        console.log(''¿Es válido (FES >= FNF)?:'', validoFES);\n        \n        if (!validoFES) {\n            console.log(''❌ VALIDACIÓN 2 FALLIDA'');\n            throw new Error(''La Fecha de Ejecución no puede ser anterior a la Fecha de Notificación Firme'');\n        }\n        \n        console.log(''✅ VALIDACIÓN 2 EXITOSA (FES >= FNF)'');\n    } else {\n        console.log(''⚠️ FES o FNF no existe, saltando validación 2'');\n    }\n    \n    console.log(''✅ TODAS LAS VALIDACIONES DEL PASO COMPLETADAS'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', NULL, NULL, 'b0798b97-4e5f-42c5-8633-e1758caf7125', '2025-11-24 00:38:27.962+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('cc3ed2f4-fd6b-46bc-ac3c-126d6096ee4e', 'validacion fecha notificación firme', 'valida_frf', 'exec', 56, 19, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== VALIDACIÓN 3: fechaNotificacionFirme >= fechaResolucionFirme Y fechaEjecucion >= fechaNotificacionFirme ==='');\n    \n    const fr = data.$last.fechaResolucion;\n    const fn = data.$last.fechaNotificacion;\n    const frf = data.$last.fechaResolucionFirme;\n    const fnf = data.$last.fechaNotificacionFirme;\n    const fes = data.$last.fechaEjecucion;\n    \n    console.log(''fechaResolucionFirme:'', frf);\n    console.log(''fechaNotificacionFirme:'', fnf);\n    console.log(''fechaEjecucion:'', fes);\n    \n    // Validación 1: FNF >= FRF\n    if (fnf && frf) {\n        const timestampFNF = new Date(fnf).getTime();\n        const timestampFRF = new Date(frf).getTime();\n        \n        console.log(''Timestamp FNF:'', timestampFNF);\n        console.log(''Timestamp FRF:'', timestampFRF);\n        \n        const validoFNF = timestampFNF >= timestampFRF;\n        console.log(''¿Es válido (FNF >= FRF)?:'', validoFNF);\n        \n        if (!validoFNF) {\n            console.log(''❌ VALIDACIÓN 1 FALLIDA'');\n            throw new Error(''La Fecha de Notificación de la Resolución Firme no puede ser anterior a la Fecha de la Resolución Firme'');\n        }\n        \n        console.log(''✅ VALIDACIÓN 1 EXITOSA (FNF >= FRF)'');\n    } else {\n        console.log(''⚠️ FNF o FRF no existe, saltando validación 1'');\n    }\n    \n    // Validación 2: FES >= FNF\n    if (fes && fnf) {\n        const timestampFES = new Date(fes).getTime();\n        const timestampFNF = new Date(fnf).getTime();\n        \n        console.log(''Timestamp FES:'', timestampFES);\n        console.log(''Timestamp FNF:'', timestampFNF);\n        \n        const validoFES = timestampFES >= timestampFNF;\n        console.log(''¿Es válido (FES >= FNF)?:'', validoFES);\n        \n        if (!validoFES) {\n            console.log(''❌ VALIDACIÓN 2 FALLIDA'');\n            throw new Error(''La Fecha de Ejecución no puede ser anterior a la Fecha de Notificación Firme'');\n        }\n        \n        console.log(''✅ VALIDACIÓN 2 EXITOSA (FES >= FNF)'');\n    } else {\n        console.log(''⚠️ FES o FNF no existe, saltando validación 2'');\n    }\n    \n    console.log(''✅ TODAS LAS VALIDACIONES DEL PASO COMPLETADAS'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', NULL, NULL, '6f1a5ebe-b90c-4b7e-b9f2-6449c29ea743', '2025-11-26 00:17:30.29+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('564c17c9-54e2-4462-9348-4c552d06fd07', 'validacion fecha notificación firme', 'valida_frf', 'exec', 56, 19, '{"code":"module.exports = async function(data) {\n    console.log(''\\n=== VALIDACIÓN 3: fechaNotificacionFirme >= fechaResolucionFirme Y fechaEjecucion >= fechaNotificacionFirme ==='');\n    \n    const fr = data.$last.fechaResolucion;\n    const fn = data.$last.fechaNotificacion;\n    const frf = data.$last.fechaResolucionFirme;\n    const fnf = data.$last.fechaNotificacionFirme;\n    const fes = data.$last.fechaEjecucion;\n    \n    console.log(''fechaResolucionFirme:'', frf);\n    console.log(''fechaNotificacionFirme:'', fnf);\n    console.log(''fechaEjecucion:'', fes);\n    \n    // Validación 1: FNF >= FRF\n    if (fnf && frf) {\n        const timestampFNF = new Date(fnf).getTime();\n        const timestampFRF = new Date(frf).getTime();\n        \n        console.log(''Timestamp FNF:'', timestampFNF);\n        console.log(''Timestamp FRF:'', timestampFRF);\n        \n        const validoFNF = timestampFNF >= timestampFRF;\n        console.log(''¿Es válido (FNF >= FRF)?:'', validoFNF);\n        \n        if (!validoFNF) {\n            console.log(''❌ VALIDACIÓN 1 FALLIDA'');\n            throw new Error(''La Fecha de Notificación de la Resolución Firme no puede ser anterior a la Fecha de la Resolución Firme'');\n        }\n        \n        console.log(''✅ VALIDACIÓN 1 EXITOSA (FNF >= FRF)'');\n    } else {\n        console.log(''⚠️ FNF o FRF no existe, saltando validación 1'');\n    }\n    \n    // Validación 2: FES >= FNF\n    if (fes && fnf) {\n        const timestampFES = new Date(fes).getTime();\n        const timestampFNF = new Date(fnf).getTime();\n        \n        console.log(''Timestamp FES:'', timestampFES);\n        console.log(''Timestamp FNF:'', timestampFNF);\n        \n        const validoFES = timestampFES >= timestampFNF;\n        console.log(''¿Es válido (FES >= FNF)?:'', validoFES);\n        \n        if (!validoFES) {\n            console.log(''❌ VALIDACIÓN 2 FALLIDA'');\n            throw new Error(''La Fecha de Ejecución no puede ser anterior a la Fecha de Notificación Firme'');\n        }\n        \n        console.log(''✅ VALIDACIÓN 2 EXITOSA (FES >= FNF)'');\n    } else {\n        console.log(''⚠️ FES o FNF no existe, saltando validación 2'');\n    }\n    \n    console.log(''✅ TODAS LAS VALIDACIONES DEL PASO COMPLETADAS'');\n    \n    return {\n        valido: true,\n        fechaResolucion: fr,\n        fechaNotificacion: fn,\n        fechaResolucionFirme: frf,\n        fechaNotificacionFirme: fnf,\n        fechaEjecucion: fes\n    };\n};"}', NULL, NULL, 'd5fdb86f-1a1b-4828-be82-f046907940ba', '2025-11-26 00:12:47.946+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('be4a40ff-97e0-4519-bd14-2448ec8d0cb8', 'Leer datos', 'leer_registro', 'item-read', 38, 1, '{"collection":"faltas_graves_personas_morales","query":{"keys":["{{$trigger.keys[0]}}"],"fields":["*","resolucion.*"]}}', '7b92bb08-e3e2-4e87-b3fd-4f65adfdb3d8', NULL, 'd5fdb86f-1a1b-4828-be82-f046907940ba', '2025-11-26 00:12:36.852+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('58bb2108-6d3a-4079-9d9f-29802bce74ab', 'Leer datos', 'leer_registro', 'item-read', 38, 1, '{"collection":"faltas_administrativas_no_graves","query":{"keys":["{{$trigger.keys[0]}}"],"fields":["*","resolucion.*"]}}', '74a3ce53-ccc3-42bd-a3dc-e864f62d2d9b', NULL, 'cf3855aa-ca21-4544-a1f7-ee3351d274cc', '2025-11-26 00:06:42.555+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e62e97b6-719b-4839-a3f0-65b84a32b00b', 'Ejecutar script', 'datosBooleanosU', 'exec', 89, 17, '{"code":"module.exports = async function(data) {\n  // Acceso seguro a los datos (evita crash si viene undefined)\n  const p = data.leer_datos?.[0]?.datosGenerales || {};\n  const d = data.$trigger?.payload?.datosGenerales || {};\n\n  // Obtenemos CURP y RFC\n  const curp = (d.curp || p.curp || '''').toUpperCase().trim();\n  const rfc = (d.rfc || p.rfc || '''').toUpperCase().trim();\n\n  // Las iniciales ya vienen calculadas, limpias y con la X si era necesaria\n  // desde el paso anterior.\n  const inicialesCalculadas = (data.inicialesEsperadasU?.inicialesEsperadas || '''').toUpperCase();\n\n  console.log(\"Iniciales Calculadas (Script 1):\", inicialesCalculadas);\n  console.log(\"CURP Usuario:\", curp);\n  console.log(\"RFC Usuario:\", rfc);\n\n  // --- VALIDACIÓN ---\n  // Solo tomamos los primeros 4 caracteres de lo que el usuario escribió\n  const curpPrefix = curp.slice(0, 4);\n  const rfcPrefix = rfc.slice(0, 4);\n\n  // Comparamos directamente.\n  // Nota: inicialesCalculadas SIEMPRE debe tener 4 letras si el script 1 funcionó bien.\n  const curpCoincide = curpPrefix === inicialesCalculadas;\n  \n  // Para el RFC a veces validan solo 3 letras si es Persona Moral, \n  // pero como aquí son nombres de persona física, deben ser 4.\n  const rfcCoincide = rfcPrefix === inicialesCalculadas;\n\n  console.log(`Coincidencia CURP: ${curpCoincide} | Coincidencia RFC: ${rfcCoincide}`);\n\n  return { \n      curpCoincide, \n      rfcCoincide, \n      curpPrefix, \n      rfcPrefix,\n      inicialesEsperadas: inicialesCalculadas \n  };\n};"}', 'ef574dda-140b-4fc9-9bf8-25db2eb5a46e', NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 17:35:51.219+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5f1bc1bc-acad-4579-9a06-0c3c5f7996e4', 'Ejecutar script', 'exec_xikiw', 'exec', 50, 1, '{"code":"module.exports = async function (data) {\n  const trigger = data.$trigger || {};\n  const payload = trigger.payload || {};\n  const payloadDG = payload.datosGenerales || {};\n\tconsole.log(data)\n  const reg = Array.isArray(data.$last) && data.$last.length > 0\n    ? data.$last[0]\n    : null;\n\n  if (!reg || !reg.datosGenerales) {\n    console.log(\"⚠ No se pudo obtener datosGenerales desde BD.\");\n    return {};\n  }\n\n  const dbDG = reg.datosGenerales;\n\n  // --- Unificación ---\n  const nombres = payloadDG.nombres || dbDG.nombres || \"\";\n  const primerApellido = payloadDG.primerApellido || dbDG.primerApellido || \"\";\n  const segundoApellido = payloadDG.segundoApellido || dbDG.segundoApellido || \"\";\n\n  const curp = payloadDG.curp || dbDG.curp || \"\";\n  const rfc = payloadDG.rfc || dbDG.rfc || \"\";\n  const expediente = payload.expediente || reg.expediente || \"\";\n    \n  const nombreRazonSocial = payload.nombreRazonSocial || dbDG.nombreRazonSocial || \"\";\n\n  // --- Construcción de valores finales ---\n  const busqueda_nombre = [nombres, primerApellido, segundoApellido].filter(Boolean).join(\" \");\n\n  const busqueda_personalizada = [\n    busqueda_nombre,\n    nombreRazonSocial,\n    rfc,\n    curp,\n    expediente\n  ].filter(Boolean).join(\" \");\n\n  console.log(\"🧩 Búsqueda generada:\", {\n    busqueda_personalizada\n  });\n\n  return busqueda_personalizada;\n};"}', 'fd09eeda-f4b0-42a0-b77d-b2b5058eeb5a', NULL, '4c039908-6256-4d97-8f14-71b8532898cc', '2025-11-19 23:31:53.045+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('09ed12df-5114-488b-adac-a298ad976581', 'Registrar en la consola', 'log_iqqit', 'log', 19, 1, '{"message":"{{$trigger}},{{$accountability}}"}', '2675613c-a1d5-4d55-b463-37f3a520d533', NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-03 23:41:08.687+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('48883a6c-0a01-410d-86e3-108ef9932d14', 'Registrar en la consola', 'log_9whah', 'log', 52, 1, '{"message":"{{inicialesEsperadas}},🤢🤢🤢🤢🤢🤢"}', '8d844947-59a8-4c70-9090-332ea8addd6f', NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 00:15:47.716+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c4b16bd4-1dc0-4eeb-a41c-f80383afd519', 'Registrar en la consola', 'log_fkrsg', 'log', 36, 17, '{"message":"😊{{leer_datos}}"}', 'c16e2797-1e93-4f3f-9b1c-b32a84752dfc', NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 17:28:56.926+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('aa93ab3e-e5a9-4a20-8fba-4aa09a8428b4', 'Leer Datos', 'leer_datos', 'item-read', 19, 17, '{"collection":"{{$trigger.collection}}","query":{"filter":{"id":{"_eq":"{{ $trigger.keys[0] }}"}},"fields":["*","datosGenerales.*"]}}', 'c4b16bd4-1dc0-4eeb-a41c-f80383afd519', NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 17:28:56.933+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c16e2797-1e93-4f3f-9b1c-b32a84752dfc', 'Ejecutar script', 'inicialesEsperadasU', 'exec', 54, 17, '{"code":"module.exports = async function(data) {\n  const p = data.leer_datos[0].datosGenerales;\n  const d = data.$trigger.payload?.datosGenerales;\n    console.log(p,\"❤️\")\n    console.log(data,\"🤣\")\n \n    let nombres =\n      d?.nombres ||\n      p.nombres;   \n \n    \n   let primerApellido =\n      d?.primerApellido ||\n      p.primerApellido;\n    \n let segundoApellido =\n    d && ''segundoApellido'' in d\n      ? d.segundoApellido ?? ''''\n      : p.segundoApellido ?? '''';   \n    \n      // --- HELPER 1: Quitar acentos y diéresis (NORMALIZACIÓN CRÍTICA) ---\n  function normalizarTexto(texto) {\n    if (!texto) return \"\";\n    return texto\n      .toUpperCase()\n      .normalize(\"NFD\") // Descompone caracteres (ej. É -> E + ´)\n      .replace(/[\\u0300-\\u036f]/g, \"\") // Elimina los acentos\n      .trim(); \n      // Nota: La Ñ se mantiene como Ñ en NFD, o se separa n + ~. \n      // Para CURP la Ñ se trata aparte, pero NFD a veces da problemas con la ñ.\n      // Mejor estrategia simple para Node: replace manual de acentos si NFD da lata,\n      // pero NFD suele respetar la Ñ base si no se filtra mal. \n      // Para seguridad total usamos un replace manual de vocales acentuadas:\n  }\n  \n  function limpiarString(str) {\n      let s = str.toUpperCase().trim();\n      // Mapeo directo para asegurar consistencia\n      const map = { ''Á'':''A'', ''É'':''E'', ''Í'':''I'', ''Ó'':''O'', ''Ú'':''U'', ''Ü'':''U'' };\n      s = s.replace(/[ÁÉÍÓÚÜ]/g, l => map[l]);\n      return s;\n  }\n\n  nombres = limpiarString(nombres);\n  primerApellido = limpiarString(primerApellido);\n  segundoApellido = limpiarString(segundoApellido);\n\n  // --- HELPER 2: Limpieza de Artículos y Preposiciones ---\n  // Se usan palabras SUELTAS. Si viene \"DE LA\", el while borrará \"DE\" y luego \"LA\".\n  const particulas = new Set([\n    \"DA\", \"DAS\", \"DE\", \"DEL\", \"DER\", \"DI\", \"DIE\", \"DD\", \"EL\", \"LA\", \"LOS\", \"LAS\", \"LE\", \"LES\", \n    \"MAC\", \"MC\", \"VAN\", \"VON\", \"Y\"\n  ]);\n\n  function quitarParticulas(str) {\n    const palabras = str.split(/\\s+/);\n    while (palabras.length > 0 && particulas.has(palabras[0])) {\n      palabras.shift();\n    }\n    return palabras.join(\" \");\n  }\n\n  // Limpiamos apellidos ANTES de procesar Ñ para que \"DE LA ÑAÑEZ\" quede \"ÑAÑEZ\"\n  primerApellido = quitarParticulas(primerApellido);\n  segundoApellido = quitarParticulas(segundoApellido);\n\n  // --- A) Selección de Nombre (Ignorar Jose/Maria) ---\n  const nombresIgnorar = [\"JOSE\", \"J\", \"J.\", \"MARIA\", \"MA\", \"MA.\"];\n  const partesNombre = nombres.split(/\\s+/);\n  \n  let nombreParaCURP = partesNombre[0];\n  \n  // Si hay más de un nombre Y el primero es ignorables\n  if (partesNombre.length > 1 && nombresIgnorar.includes(partesNombre[0])) {\n    nombreParaCURP = partesNombre[1]; // Tomamos el segundo\n  }\n\n  // IMPORTANTE: Limpiar partículas del nombre elegido (Caso \"Maria Del Carmen\")\n  nombreParaCURP = quitarParticulas(nombreParaCURP);\n\n\n   const tratarÑ = (str) => str.startsWith(\"Ñ\") ? \"X\" + str.slice(1) : str;\n\n  primerApellido = tratarÑ(primerApellido);\n  segundoApellido = tratarÑ(segundoApellido);\n  nombreParaCURP = tratarÑ(nombreParaCURP);\n\n  // --- C) Extracción de Letras ---\n  \n  // 1. Inicial Primer Apellido\n  const inicialPA = primerApellido[0] || \"X\";\n\n  // 2. Vocal Interna Primer Apellido\n  // Buscamos vocal en el resto de la palabra. Si no hay, es X.\n  // Excluimos la primera letra con slice(1)\n  const vocalInterna = (primerApellido.slice(1).match(/[AEIOU]/) || [\"X\"])[0];\n\n  // 3. Inicial Segundo Apellido (Si no existe, es X)\n  const inicialSA = segundoApellido ? segundoApellido[0] : \"X\";\n\n  // 4. Inicial Nombre\n  const inicialNombre = nombreParaCURP[0] || \"X\";\n\n  let iniciales = (inicialPA + vocalInterna + inicialSA + inicialNombre);\n\n  // --- D) Palabras Antisonantes (Lista Oficial Completa) ---\n  // Si se forma una de estas, la vocal (posición 2) se cambia por X\n  const prohibidas = new Set([\n    \"BACA\", \"BAJA\", \"BUEI\", \"BUEY\", \"CACA\", \"CACO\", \"CAGA\", \"CAGO\", \"CAKA\", \"CAKO\",\n    \"COGE\", \"COGI\", \"COJA\", \"COJE\", \"COJI\", \"COJO\", \"COLA\", \"CULO\", \"FALO\", \"FETO\",\n    \"GETA\", \"GUEI\", \"GUEY\", \"JETA\", \"JOTO\", \"KACA\", \"KACO\", \"KAGA\", \"KAGO\", \"KAKA\",\n    \"KAKO\", \"KOGE\", \"KOGI\", \"KOJA\", \"KOJE\", \"KOJI\", \"KOJO\", \"KOLA\", \"KULO\", \"LILO\",\n    \"LOCA\", \"LOCO\", \"LOKA\", \"LOKO\", \"MAME\", \"MAMO\", \"MEAR\", \"MEAS\", \"MEON\", \"MIAR\",\n    \"MION\", \"MOCO\", \"MOKO\", \"MULA\", \"MULO\", \"NACA\", \"NACO\", \"PEDA\", \"PEDO\", \"PENE\",\n    \"PIPI\", \"PITO\", \"POPO\", \"PUTA\", \"PUTO\", \"QULO\", \"RATA\", \"ROBA\", \"ROBE\", \"ROBO\",\n    \"RUIN\", \"SENO\", \"TETA\", \"VACA\", \"VAGA\", \"VAGO\", \"VAKA\", \"VUEI\", \"VUEY\", \"WUEI\",\n    \"WUEY\"\n  ]);\n\n  if (prohibidas.has(iniciales)) {\n    // Reemplazar la segunda letra (vocal) por X\n    iniciales = iniciales[0] + \"X\" + iniciales.slice(2);\n  }\n        console.log(iniciales,\"💕😒⚽🤐🤢\")\n\n  return { inicialesEsperadas: iniciales };\n};"}', 'fa7103dc-a66f-48d9-a453-0cff58b06681', NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 17:31:03.665+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8d844947-59a8-4c70-9090-332ea8addd6f', 'Ejecutar script', 'datosBooleanos', 'exec', 69, 1, '{"code":"module.exports = async function(data) {\n  const p = data.$trigger.payload.datosGenerales;\n  const { segundoApellido} = p;\n  const iniciales = data.inicialesEsperadas.inicialesEsperadas;\n  // Obtenemos CURP y RFC (Limpiamos espacios y mayúsculas)\n  const curp = (p.curp || '''').toUpperCase().trim();\n  const rfc = (p.rfc || '''').toUpperCase().trim();\n\n  // Obtenemos las iniciales calculadas del paso anterior\n  // NOTA: Asegúrate que el nombre del paso anterior sea ''inicialesEsperadas''\n  // Si en tu flujo Create el paso se llama diferente, ajusta ''data.inicialesEsperadas'' abajo\n  const inicialesCalculadas = (data.inicialesEsperadas?.inicialesEsperadas || '''').toUpperCase();\n\n  console.log(\"Iniciales Calculadas:\", inicialesCalculadas);\n  console.log(\"Input Usuario - CURP:\", curp, \"RFC:\", rfc);\n\n  // --- VALIDACIÓN SIMPLIFICADA ---\n  const curpPrefix = curp.slice(0, 4);\n  const rfcPrefix = rfc.slice(0, 4);\n\n  // Comparación directa (=== es más seguro y estricto)\n  const curpCoincide = curpPrefix === inicialesCalculadas;\n  const rfcCoincide = rfcPrefix === inicialesCalculadas;\n\n  console.log(`Coincide CURP: ${curpCoincide} | Coincide RFC: ${rfcCoincide}`);\n\n  return { \n      curpCoincide, \n      rfcCoincide, \n      curpPrefix, \n      rfcPrefix \n  };\n};"}', 'c819fcd7-40dd-49b0-90ae-16cba0ed7c28', NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 00:15:47.699+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c819fcd7-40dd-49b0-90ae-16cba0ed7c28', 'Ejecutar script', 'exec_pj6o2', 'exec', 86, 1, '{"code":"module.exports = async function (data) {\n  const iniciales = data.inicialesEsperadas?.inicialesEsperadas || ''N/A'';\n  const { curpPrefix, rfcPrefix, curpCoincide, rfcCoincide } = data.datosBooleanos || {};\n\n  // 🧩 Caso 1: Ambos incorrectos\n  if (!curpCoincide && !rfcCoincide) {\n    throw new Error(\n      `❌ Inconsistencia detectada: \n      Las iniciales esperadas (${iniciales}) no coinciden ni con la CURP (${curpPrefix}) ni con el RFC (${rfcPrefix}). \n      Verifica que nombre, apellidos, CURP y RFC correspondan correctamente.`\n    );\n  }\n\n  // 🧩 Caso 2: Solo CURP incorrecta\n  if (!curpCoincide && rfcCoincide) {\n    throw new Error(\n      `⚠️ Inconsistencia parcial:\n      Las iniciales esperadas (${iniciales}) coinciden con el RFC (${rfcPrefix}) pero no con la CURP (${curpPrefix}). \n      Revisa la CURP, podría haberse capturado de forma incorrecta.`\n    );\n  }\n\n  // 🧩 Caso 3: Solo RFC incorrecta\n  if (curpCoincide && !rfcCoincide) {\n    throw new Error(\n      `⚠️ Inconsistencia parcial:\n      Las iniciales esperadas (${iniciales}) coinciden con la CURP (${curpPrefix}) pero no con el RFC (${rfcPrefix}). \n      Revisa el RFC, podría haberse capturado de forma incorrecta.`\n    );\n  }\n\n  // ✅ Caso 4: Todo correcto\n  return {\n    message: `✅ Validación CURP/RFC exitosa: las iniciales (${iniciales}) coinciden correctamente con la CURP (${curpPrefix}) y el RFC (${rfcPrefix}).`\n  };\n};\n\n"}', NULL, NULL, '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 00:49:42.088+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('747cc248-c5bc-49ef-86e5-8ff7f1a7ff23', 'Registrar en la consola', 'log_kkbzd', 'log', 31, 35, '{"message":"😒😒😒😒😒😒😒😒😒😒😒😒"}', '1974daa8-257d-4d6f-92ea-26bef2236098', NULL, '77777777-7777-7777-7777-777777777777', '2025-11-26 19:46:47.557+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2675613c-a1d5-4d55-b463-37f3a520d533', 'Ejecutar script', 'inicialesEsperadas', 'exec', 36, 1, '{"code":"module.exports = async function(data) {\n    if (data.$trigger && data.$trigger.event.includes(\"update\")) {\n        throw new Error(\"⛔ DETENIDO: Es un UPDATE y este script es solo para CREATE.\");\n    }\n    // 1. OBTENCIÓN DE DATOS\n    // Usamos encadenamiento opcional ?. para evitar errores iniciales\n    const p = data?.$trigger?.payload?.datosGenerales;\n\n    // --- CLÁUSULA DE GUARDIA (AQUÍ ESTÁ LA SOLUCIÓN) ---\n    // Si p no existe (es undefined o null), devolvemos una señal para ir a la \"X\"\n\n\n    // --- COMIENZO DEL PROCESO NORMAL ---\n    function safeStr(val) {\n        if (val === null || val === undefined) return \"\";\n        return String(val).toUpperCase().trim();\n    }\n\n    // Ahora es seguro acceder a p.nombres porque ya validamos que p existe\n    let nombres = safeStr(p.nombres);\n    let primerApellido = safeStr(p.primerApellido);\n    let segundoApellido = safeStr(p.segundoApellido);\n\n    // ... (El resto de tu código sigue IGUAL hacia abajo) ...\n\n    // --- HELPER: Limpieza de acentos ---\n    function limpiarString(str) {\n        const map = { ''Á'': ''A'', ''É'': ''E'', ''Í'': ''I'', ''Ó'': ''O'', ''Ú'': ''U'', ''Ü'': ''U'' };\n        return str.replace(/[ÁÉÍÓÚÜ]/g, l => map[l])\n            .normalize(\"NFD\").replace(/[\\u0300-\\u036f]/g, \"\");\n    }\n\n    nombres = limpiarString(nombres);\n    primerApellido = limpiarString(primerApellido);\n    segundoApellido = limpiarString(segundoApellido);\n\n    // --- HELPER: Quitar Partículas ---\n    const particulas = new Set([\n        \"DA\", \"DAS\", \"DE\", \"DEL\", \"DER\", \"DI\", \"DIE\", \"DD\", \"EL\", \"LA\", \"LOS\", \"LAS\", \"LE\", \"LES\",\n        \"MAC\", \"MC\", \"VAN\", \"VON\", \"Y\"\n    ]);\n\n    function quitarParticulas(str) {\n        const palabras = str.split(/\\s+/);\n        while (palabras.length > 0 && particulas.has(palabras[0])) {\n            palabras.shift();\n        }\n        return palabras.join(\" \");\n    }\n\n    primerApellido = quitarParticulas(primerApellido);\n    segundoApellido = quitarParticulas(segundoApellido);\n\n    // --- LÓGICA: Selección de Nombre ---\n    const nombresIgnorar = new Set([\"JOSE\", \"J\", \"J.\", \"MARIA\", \"MA\", \"MA.\"]);\n    const partesNombre = nombres.split(/\\s+/);\n\n    let nombreParaCURP = partesNombre[0] || \"\";\n\n    if (partesNombre.length > 1 && nombresIgnorar.has(partesNombre[0])) {\n        nombreParaCURP = partesNombre[1];\n    }\n\n    nombreParaCURP = quitarParticulas(nombreParaCURP);\n\n    // --- LÓGICA: Manejo de Ñ ---\n    const tratarÑ = (str) => (!str) ? \"X\" : (str.startsWith(\"Ñ\") ? \"X\" + str.slice(1) : str);\n\n    primerApellido = tratarÑ(primerApellido);\n    segundoApellido = tratarÑ(segundoApellido);\n    nombreParaCURP = tratarÑ(nombreParaCURP);\n\n    // --- EXTRACCIÓN DE LETRAS ---\n    const inicialPA = primerApellido.charAt(0) || \"X\";\n    const matchVocal = primerApellido.slice(1).match(/[AEIOU]/);\n    const vocalInterna = matchVocal ? matchVocal[0] : \"X\";\n\n    const inicialSA = segundoApellido.charAt(0) || \"X\";\n    const inicialNombre = nombreParaCURP.charAt(0) || \"X\";\n\n    let iniciales = inicialPA + vocalInterna + inicialSA + inicialNombre;\n\n    // --- LÓGICA: Palabras Antisonantes ---\n    const prohibidas = new Set([\n        \"BACA\", \"BAJA\", \"BUEI\", \"BUEY\", \"CACA\", \"CACO\", \"CAGA\", \"CAGO\", \"CAKA\", \"CAKO\",\n        \"COGE\", \"COGI\", \"COJA\", \"COJE\", \"COJI\", \"COJO\", \"COLA\", \"CULO\", \"FALO\", \"FETO\",\n        \"GETA\", \"GUEI\", \"GUEY\", \"JETA\", \"JOTO\", \"KACA\", \"KACO\", \"KAGA\", \"KAGO\", \"KAKA\",\n        \"KAKO\", \"KOGE\", \"KOGI\", \"KOJA\", \"KOJE\", \"KOJI\", \"KOJO\", \"KOLA\", \"KULO\", \"LILO\",\n        \"LOCA\", \"LOCO\", \"LOKA\", \"LOKO\", \"MAME\", \"MAMO\", \"MEAR\", \"MEAS\", \"MEON\", \"MIAR\",\n        \"MION\", \"MOCO\", \"MOKO\", \"MULA\", \"MULO\", \"NACA\", \"NACO\", \"PEDA\", \"PEDO\", \"PENE\",\n        \"PIPI\", \"PITO\", \"POPO\", \"PUTA\", \"PUTO\", \"QULO\", \"RATA\", \"ROBA\", \"ROBE\", \"ROBO\",\n        \"RUIN\", \"SENO\", \"TETA\", \"VACA\", \"VAGA\", \"VAGO\", \"VAKA\", \"VUEI\", \"VUEY\", \"WUEI\",\n        \"WUEY\"\n    ]);\n\n    if (prohibidas.has(iniciales)) {\n        iniciales = inicialPA + \"X\" + inicialSA + inicialNombre;\n    }\n\n    // Devolvemos cancelar false porque todo salió bien\n    return { \n        inicialesEsperadas: iniciales, \n        cancelar: false \n    };\n};"}', '48883a6c-0a01-410d-86e3-108ef9932d14', 'aa93ab3e-e5a9-4a20-8fba-4aa09a8428b4', '21ae8c9b-681f-48bc-8227-6cab1c098c31', '2025-11-04 00:06:53.274+00', NULL);
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9b38acb1-68a3-42eb-8711-515b164d37b2', 'Registrar en la consola', 'log_4gbsu', 'condition', 12, 23, '{"filter":{"$last":{"esUpdate":{"_eq":true}}}}', 'b7e8dc0e-a475-4338-a7ba-4ad090ddc4e8', '747cc248-c5bc-49ef-86e5-8ff7f1a7ff23', '77777777-7777-7777-7777-777777777777', '2025-11-26 16:45:14.4+00', 'b193f6f6-f781-4415-816f-76ced4f71039');
